// Create exact paper-space index geometry from native templates; engineering projection is caller-owned.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.EditorInput;using Autodesk.AutoCAD.ApplicationServices;
using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class NativePaperIndexCreateV1 {
 public class Template {public string handle,layer;}
 public class Item {public string key,index_label,drawing_label;public double[][] vertices;public double[] position;}
 public class Job {public string input,input_sha256,output,receipt,layout,expected_index_label;public Template boundary_template,index_template;public Item[] items;public string[] created_handles;}
 public class Host {public int pid;public long created;public string image;}
 public class Manifest {public string request,request_sha256,loaded_dll,loaded_dll_sha256,session_dir;public Host host;}
 public class Request {public string kind,job_path,job_sha256;}
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=50000000,RecursionLimit=100};static readonly BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;
 static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}static bool Eq(string a,string b){return String.Equals(Path.GetFullPath(a),Path.GetFullPath(b),StringComparison.OrdinalIgnoreCase);}
 static object Get(Type t,string n){return t.GetField(n,F).GetValue(null);}static object Call(Type t,string n,params object[] a){return t.GetMethod(n,F).Invoke(null,a);}
 static object Prop(Entity e,string k){var c=e.AcadObject;return c.GetType().InvokeMember(k,BindingFlags.GetProperty,null,c,null);}static void Set(Entity e,string k,object v){var c=e.AcadObject;c.GetType().InvokeMember(k,BindingFlags.SetProperty,null,c,new[]{v});}
 static void Write(string p,object o){using(var f=new FileStream(p,FileMode.CreateNew))using(var w=new StreamWriter(f,new System.Text.UTF8Encoding(false)))w.Write(J.Serialize(o));}
 static ObjectId Id(Database db,string h){return db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0);}static double[] A(Point3d p){return new[]{p.X,p.Y,p.Z};}
 static bool Finite(double d){return !Double.IsNaN(d)&&!Double.IsInfinity(d);}
 static ObjectId Space(Database db,Transaction tr,string name){var d=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);Need(d.Contains(name),"LAYOUT_MISSING");var l=(Layout)tr.GetObject(d.GetAt(name),OpenMode.ForRead);Need(!l.ModelType,"PAPER_LAYOUT_ONLY");return l.BlockTableRecordId;}
 static Entity Open(Database db,Transaction tr,Template t,string layout,string type){var e=tr.GetObject(Id(db,t.handle),OpenMode.ForRead) as Entity;Need(e!=null&&e.GetRXClass().Name==type&&e.Layer==t.layer&&e.OwnerId==Space(db,tr,layout),"TEMPLATE_IDENTITY_CHANGED:"+t.handle);Need(!((LayerTableRecord)tr.GetObject(e.LayerId,OpenMode.ForRead)).IsLocked,"TEMPLATE_LAYER_LOCKED");return e;}
 static double[][] Grips(Entity e){var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);return g.Cast<GripData>().Select(x=>A(x.GripPoint)).ToArray();}
 static string[] IndexKeys={"IndexLabel","DrawingLabel","Scale","LayoutRotation","ObjectControl","FontStyle","ShowName","NameStyle","NameText","NameHeight","ShowScale","ScaleStyle","ScaleText","ScaleHeight","TextColor","TextLayer","Diameter","LineWeight","OldStyle","TextRatio","Text2BaseRatio","OutsideText","MaskFlag"};
 static object Display(Entity e){return new{type=e.GetRXClass().Name,layer=e.Layer,color=e.Color.ToString(),linetype=e.Linetype,linetype_scale=e.LinetypeScale,lineweight=(int)e.LineWeight,visible=e.Visible,transparency=e.Transparency.ToString()};}
 static Dictionary<string,object> Props(Entity e){return IndexKeys.ToDictionary(k=>k,k=>Prop(e,k));}
 static object Shape(Entity e){var p=e as Polyline;if(p!=null)return new{closed=p.Closed,normal=A(Point3d.Origin+p.Normal),elevation=p.Elevation,thickness=p.Thickness,plinegen=p.Plinegen,vertices=Enumerable.Range(0,p.NumberOfVertices).Select(k=>new[]{p.GetPoint2dAt(k).X,p.GetPoint2dAt(k).Y,p.GetBulgeAt(k),p.GetStartWidthAt(k),p.GetEndWidthAt(k)}).ToArray()};return new{properties=Props(e),grips=Grips(e)};}
 static object Row(Entity e){return new{handle=e.Handle.ToString(),owner=e.OwnerId.Handle.ToString(),display=Display(e),shape=Shape(e)};}
 static string Snapshot(Database db,Job job,string[] added){var prev=HostApplicationServices.WorkingDatabase;try{HostApplicationServices.WorkingDatabase=db;using(var tr=db.TransactionManager.StartTransaction()){var handles=new[]{job.boundary_template.handle,job.index_template.handle}.Concat(added??new string[0]);return J.Serialize(handles.Select(h=>Row((Entity)tr.GetObject(Id(db,h),OpenMode.ForRead))).ToArray());}}finally{HostApplicationServices.WorkingDatabase=prev;}}
 static void Validate(Job j){Need(j.items!=null&&j.items.Length>0&&j.items.All(i=>i!=null&&!String.IsNullOrEmpty(i.key)&&!String.IsNullOrEmpty(i.index_label))&&j.items.Select(i=>i.key).Distinct().Count()==j.items.Length,"UNIQUE_ITEMS_REQUIRED");foreach(var i in j.items){Need(i.vertices!=null&&i.vertices.Length>=3&&i.vertices.All(v=>v!=null&&v.Length==2&&v.All(Finite)),"EXACT_PAPER_XY_VERTICES_REQUIRED");for(int k=0;k<i.vertices.Length;k++)Need(!i.vertices[k].SequenceEqual(i.vertices[(k+1)%i.vertices.Length]),"ZERO_LENGTH_SEGMENT");Need(i.position!=null&&i.position.Length==2&&i.position.All(Finite),"INDEX_CENTER_XY_REQUIRED");}}
 public static object Apply(Database db,Job job,Action mutation,Action committed){Validate(job);var added=new List<string>();var results=new List<object>();var touched=new HashSet<string>();var appended=new HashSet<string>();
  ObjectEventHandler modified=(s,a)=>{if(a.DBObject is Entity&&!a.DBObject.IsNewObject&&!added.Contains(a.DBObject.Handle.ToString()))touched.Add(a.DBObject.Handle.ToString());};ObjectEventHandler app=(s,a)=>{if(a.DBObject is Entity)appended.Add(a.DBObject.Handle.ToString());};ObjectErasedEventHandler erase=(s,a)=>{if(a.Erased&&a.DBObject is Entity)touched.Add(a.DBObject.Handle.ToString());};
  using(var tr=db.TransactionManager.StartTransaction()){
   var source=(Polyline)Open(db,tr,job.boundary_template,job.layout,"AcDbPolyline");var index=Open(db,tr,job.index_template,job.layout,"TDbSymbDrawingIndex");Need(source.Normal.IsEqualTo(Vector3d.ZAxis)&&source.Elevation==0,"PLANAR_PAPER_TEMPLATE_REQUIRED");double width=source.ConstantWidth;Need(Finite(width)&&width>=0,"UNIFORM_TEMPLATE_WIDTH_REQUIRED");Need(Convert.ToString(Prop(index,"IndexLabel"))==job.expected_index_label,"INDEX_TEMPLATE_LABEL_CHANGED");var grips=Grips(index);Need(grips.Length==2&&grips.All(g=>Math.Abs(g[2])<1e-9),"TWO_GRIP_PLANAR_INDEX_REQUIRED");var indexProps=Props(index);string sourceState=J.Serialize(new[]{Row(source),Row(index)});var paper=(BlockTableRecord)tr.GetObject(source.OwnerId,OpenMode.ForWrite);
   db.ObjectModified+=modified;db.ObjectAppended+=app;db.ObjectErased+=erase;
   try{mutation();foreach(var i in job.items){
    var line=new Polyline();line.SetPropertiesFrom(source);line.Normal=source.Normal;line.Elevation=source.Elevation;line.Thickness=source.Thickness;line.Plinegen=source.Plinegen;for(int k=0;k<i.vertices.Length;k++)line.AddVertexAt(k,new Point2d(i.vertices[k][0],i.vertices[k][1]),0,width,width);line.Closed=true;paper.AppendEntity(line);tr.AddNewlyCreatedDBObject(line,true);added.Add(line.Handle.ToString());
    var mapping=new IdMapping();db.DeepCloneObjects(new ObjectIdCollection(new[]{index.ObjectId}),paper.ObjectId,mapping,false);Need(mapping.Contains(index.ObjectId),"NATIVE_DEEP_CLONE_MAP_REQUIRED");var clone=(Entity)tr.GetObject(mapping[index.ObjectId].Value,OpenMode.ForWrite);added.Add(clone.Handle.ToString());Set(clone,"IndexLabel",i.index_label);if(i.drawing_label!=null)Set(clone,"DrawingLabel",i.drawing_label);var delta=new Vector3d(i.position[0]-grips[0][0],i.position[1]-grips[0][1],0);clone.TransformBy(Matrix3d.Displacement(delta));
    var expected=new Dictionary<string,object>(indexProps);expected["IndexLabel"]=i.index_label;if(i.drawing_label!=null)expected["DrawingLabel"]=i.drawing_label;
    Need(CadValueCompareV1.Json(J.Serialize(expected),J.Serialize(Props(clone))),"INDEX_PROPERTIES_CHANGED");var actual=Grips(clone);Need(actual.Length==grips.Length,"INDEX_TOPOLOGY_CHANGED");for(int k=0;k<grips.Length;k++)Need(new Point3d(actual[k][0],actual[k][1],actual[k][2]).DistanceTo(new Point3d(grips[k][0],grips[k][1],grips[k][2])+delta)<1e-7,"INDEX_GRIPS_NOT_TRANSLATED");Need(CadValueCompareV1.Json(J.Serialize(Display(source)),J.Serialize(Display(line)))&&CadValueCompareV1.Json(J.Serialize(Display(index)),J.Serialize(Display(clone))),"TEMPLATE_DISPLAY_CHANGED");results.Add(new{key=i.key,boundary=Row(line),index=Row(clone)});
   }
   Need(sourceState==J.Serialize(new[]{Row(source),Row(index)}),"SOURCE_TEMPLATE_CHANGED");Need(!touched.Except(added).Any(),"UNSELECTED_ENTITY_MODIFIED:"+String.Join(",",touched));tr.Commit();committed();Need(appended.SetEquals(added),"UNEXPECTED_APPENDED_ENTITIES:observed="+String.Join(",",appended)+";expected="+String.Join(",",added));Need(!touched.Except(added).Any(),"UNSELECTED_ENTITY_MODIFIED_AT_COMMIT:"+String.Join(",",touched));}
   finally{db.ObjectModified-=modified;db.ObjectAppended-=app;db.ObjectErased-=erase;}
  }job.created_handles=added.ToArray();return new{created=results,old_objects_preserved=true,whole_native_index=true,projection_computed=false};
 }
 static void ReopenVerify(string path,Job job,string expected){using(var saved=new Database(false,true)){saved.ReadDwgFile(path,FileOpenMode.OpenForReadAndAllShare,true,"");saved.CloseInput(true);Need(CadValueCompareV1.Json(expected,Snapshot(saved,job,job.created_handles)),"PAPER_INDEX_SAVE_REOPEN_MISMATCH");}}
 [CommandMethod("HLCADPAPERINDEXCREATEV5",CommandFlags.Session)]public void Run(){var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nPaper index creation: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Type adapter=null;Job job=null;bool owned=false,started=false,committed=false;try{
  var m=J.Deserialize<Manifest>(File.ReadAllText(a.StringResult.Trim('"')));var p=System.Diagnostics.Process.GetCurrentProcess();Need(p.Id==m.host.pid&&p.StartTime.ToUniversalTime().ToFileTimeUtc()==m.host.created&&Eq(p.MainModule.FileName,m.host.image),"HOST_IDENTITY");adapter=AppDomain.CurrentDomain.GetAssemblies().Select(x=>x.GetType("V736BaseSession",false)).Single(x=>x!=null);CadAdapterContractV1.Check(adapter);Need(Eq(adapter.Assembly.Location,m.loaded_dll)&&NativeGeometryReadV1.Hash(m.loaded_dll)==m.loaded_dll_sha256&&Eq((string)Get(adapter,"dir"),m.session_dir),"ADAPTER_IDENTITY");Need(!(bool)Get(adapter,"busy")&&!(bool)Get(adapter,"blocked")&&!File.Exists(Path.Combine(m.session_dir,"request.json")),"SESSION_BUSY");Need(Eq(Path.GetDirectoryName(m.request),m.session_dir)&&NativeGeometryReadV1.Hash(m.request)==m.request_sha256,"REQUEST_IDENTITY");var req=J.Deserialize<Request>(File.ReadAllText(m.request));Need(req.kind=="paper_index_create"&&NativeGeometryReadV1.Hash(req.job_path)==req.job_sha256,"JOB_IDENTITY");Call(adapter,"CheckPath",req.job_path);job=J.Deserialize<Job>(File.ReadAllText(req.job_path));Call(adapter,"CheckLive",job.input,job.input_sha256);Call(adapter,"CheckOutput",job.output,job.receipt);var doc=(Document)Get(adapter,"doc");Need(doc==App.DocumentManager.MdiActiveDocument,"ACTIVE_DOCUMENT_CHANGED");adapter.GetField("busy",F).SetValue(null,true);owned=true;
  using(doc.LockDocument()){var changes=Apply(doc.Database,job,()=>started=true,()=>committed=true);string expected=Snapshot(doc.Database,job,job.created_handles);doc.Database.SaveAs(job.output,DwgVersion.AC1032);ReopenVerify(job.output,job,expected);string path=Path.GetFullPath(job.output),sha=NativeGeometryReadV1.Hash(path);((Dictionary<string,string>)Get(adapter,"approved"))[path]=sha;adapter.GetField("currentPath",F).SetValue(null,path);adapter.GetField("currentHash",F).SetValue(null,sha);Write(job.receipt,new{status="SAVED_STILL_OPEN",output=path,sha256=sha,pid=p.Id,native_save_reopen_verified=true,changes=changes});Call(adapter,"State");}
 }catch(System.Exception e){string emergency=null;if(started&&adapter!=null){adapter.GetField("blocked",F).SetValue(null,true);try{var doc=(Document)Get(adapter,"doc");emergency=Path.Combine((string)Get(adapter,"dir"),"paper_index_emergency_"+Guid.NewGuid().ToString("N")+".dwg");using(doc.LockDocument())doc.Database.SaveAs(emergency,DwgVersion.AC1032);}catch{}}if(job!=null&&!File.Exists(job.receipt))Write(job.receipt,new{status=started?"BOUND_MODULE_FAILED":"REJECTED_BEFORE_WRITE",source_sha256=job.input_sha256,write_started=started,committed=committed,replayed=false,emergency=emergency,error=e.ToString()});}finally{if(owned)adapter.GetField("busy",F).SetValue(null,false);}}
}
